  END IF;
  RETURN OLD;
END
$$;
-- +goose StatementEnd
REVOKE ALL ON FUNCTION ctrlz.suspended_claim_stays() FROM PUBLIC;
CREATE TRIGGER suspended_claim_stays BEFORE DELETE ON ctrlz.ip_claims
